export function decodeClassDirectionAtlas(id,direction){const key=id+":"+direction;if(!Object.hasOwn(packed,key))return null;if(cache.has(key))return cache.get(key);const raw=atob(packed[key]),data=new Uint8Array(1024*640*4);let out=0;for(let i=0;i<raw.length;i+=6){const count=raw.charCodeAt(i)|(raw.charCodeAt(i+1)<<8),color=[raw.charCodeAt(i+2),raw.charCodeAt(i+3),raw.charCodeAt(i+4),raw.charCodeAt(i+5)];for(let n=0;n<count;n++){data.set(color,out);out+=4;}}if(out!==data.length)throw Error("Invalid directional atlas");const result={data,width:1024,height:640};cache.set(key,result);return result;}
